current_native_triggers.definition:
create trigger trg_cc_candidates
after insert or update or delete on public.candidates
for each row execute function public._trg_change_bump('candidates');

create trigger trg_cc_timesheets
after insert or update or delete on public.timesheets
for each row execute function public._trg_change_bump('timesheets');

create trigger trg_cc_invoice_lines
after insert or update or delete on public.invoice_lines
for each row execute function public._trg_change_bump('invoices');

create trigger timesheets_candidate_qr_pack_ready_notification_trg
before update of document_state,current_document_version_id on public.timesheets
for each row execute function private._candidate_qr_pack_ready_notification_v1();

create trigger trg_timesheet_authorisation_overlap_biu
before insert or update of authorised_at_server on public.timesheets
for each row execute function private._timesheet_authorisation_overlap_trg_v1();

create trigger candidate_expense_candidate_identity_summary_refresh
after update of display_name,first_name,last_name,tms_ref on public.candidates
for each row execute function private._candidate_expense_identity_summary_trigger_v1();

create trigger weekly_source_invoice_line_owner_guard
before insert or update or delete on public.invoice_lines
for each row execute function private.weekly_source_invoice_line_owner_guard_v1();

create trigger bpay_next_workbench_candidate_name_trigger after update of display_name,first_name,last_name,tms_ref,
  pay_method,umbrella_id,bank_details_hash,account_holder,sort_code,account_number on public.candidates
  for each row execute function private.bpay_next_workbench_candidate_name_trigger_v1();

create constraint trigger zz_timesheet_correction_whole_state_guard_v1 after insert or update on public.timesheets
deferrable initially deferred for each row
execute function private.timesheet_correction_whole_state_guard_v1();
